class ProtocolViolation(Enum):
    """How an authenticated runner broke the protocol.
    malformed_message: A frame was not JSON for any runner frame (an unknown `type`, a
    missing or extra field, including a handler key that does not match the published
    handler-key schema), or was a binary frame.
    not_authenticated: Reserved; not sent today. A first frame other than `authenticate` is
    answered with `authentication_failed`.
    already_authenticated: `authenticate` was sent again on an authenticated connection.
    invalid_announcement: The announcement broke a constraint: zero capacity; no, too many,
    duplicate, blank or oversized handler keys; a blank or oversized display name or runner
    version; or a blank, oversized or non-semver SDK version.
    already_announced: `announce` was sent twice on one connection. Reconnect to replace the
    announcement.
    """
    ALREADY_ANNOUNCED = "already_announced"
    ALREADY_AUTHENTICATED = "already_authenticated"
    INVALID_ANNOUNCEMENT = "invalid_announcement"
    MALFORMED_MESSAGE = "malformed_message"
    NOT_AUTHENTICATED = "not_authenticated"


