class StartCommandType(Enum):
    START = "start"


@dataclass
class StartCommand:
    """Connect, authenticate and announce, then deliver work to the scripted handlers. Answered
    by `connected` or `connect_failed`.
    """
    concurrency_capacity: int
    handlers: List[HandlerScript]
    secret_store: SecretStoreConfig
    token: str
    tron_url: str
    """The runner WebSocket URL, e.g. as printed by the harness."""

    type: StartCommandType
    display_name: Optional[str] = None
    runner_version: Optional[str] = None

    @staticmethod
    def from_dict(obj: Any) -> 'StartCommand':
        assert isinstance(obj, dict)
        concurrency_capacity = from_int(obj.get("concurrency_capacity"))
        handlers = from_list(HandlerScript.from_dict, obj.get("handlers"))
        secret_store = SecretStoreConfig.from_dict(obj.get("secret_store"))
        token = from_str(obj.get("token"))
        tron_url = from_str(obj.get("tron_url"))
        type = StartCommandType(obj.get("type"))
        display_name = from_union([from_none, from_str], obj.get("display_name"))
        runner_version = from_union([from_none, from_str], obj.get("runner_version"))
        return StartCommand(concurrency_capacity, handlers, secret_store, token, tron_url, type, display_name, runner_version)

    def to_dict(self) -> dict:
        result: dict = {}
        result["concurrency_capacity"] = from_int(self.concurrency_capacity)
        result["handlers"] = from_list(lambda x: to_class(HandlerScript, x), self.handlers)
        result["secret_store"] = to_class(SecretStoreConfig, self.secret_store)
        result["token"] = from_str(self.token)
        result["tron_url"] = from_str(self.tron_url)
        result["type"] = to_enum(StartCommandType, self.type)
        if self.display_name is not None:
            result["display_name"] = from_union([from_none, from_str], self.display_name)
        if self.runner_version is not None:
            result["runner_version"] = from_union([from_none, from_str], self.runner_version)
        return result


